prepare() {
mkdir -p /run/hostapd-u6e && chmod 700 /run/hostapd-u6e && rm -f /run/hostapd-u6e/*.conf /run/hostapd-u6e/*.vlan
getent group u6e-agent >/dev/null || groupadd -r u6e-agent
install -d -m 700 /run/u6e-wifi
mkdir -p /run/hostapd-u6e/radsec
cat > /run/hostapd-u6e/radsec/ca.pem <<'EOF'
-----BEGIN CERTIFICATE-----
TESTCA
-----END CERTIFICATE-----
EOF
cat > /run/hostapd-u6e/radsec/client.pem <<'EOF'
-----BEGIN CERTIFICATE-----
TESTCERT
-----END CERTIFICATE-----
EOF
cat > /run/hostapd-u6e/radsec/client.key <<'EOF'
-----BEGIN ENCRYPTED PRIVATE KEY-----
TESTKEY
-----END ENCRYPTED PRIVATE KEY-----
EOF
chmod 600 /run/hostapd-u6e/radsec/*
for i in wlan24 wlan5 wlan6; do
	for _ in $(seq 60); do [ -e /sys/class/net/$i ] && break; sleep 0.5; done
	ip link set $i up
done
iw reg set KR
for _ in $(seq 20); do [ "$(iw reg get | grep -c '^country KR')" -ge 3 ] && break; sleep 0.5; done
iw reg get | grep -E '^(phy|country)' | paste - - | sed 's/^/reg: /'
ls /run/u6e-wifi/wlan*.conf >/dev/null 2>&1 || (umask 077; install_confs)
render
/usr/local/sbin/u6e-agent --publish-config-hash
# The bridges the VLAN files name, and the BSSs of a previous hostapd gone from
# the radios (they outlast the process, and a radio that still has one refuses
# the new beacon).
for id in $WIFI_VLANS; do
	for _ in $(seq 60); do [ -e /sys/class/net/br$id ] && break; sleep 0.5; done
done
for _ in $(seq 20); do
	iw dev | grep -q "^[[:space:]]*ssid " || break
	sleep 0.5
done
}
render() (
set -e
for b in 24 5 6; do
	s=/run/u6e-wifi/wlan$b.conf c=/run/hostapd-u6e/wlan$b.conf a=/run/hostapd-u6e/wlan$b.address
	[ -e $s ] || continue
	[ -s $a ] || cat /sys/class/net/wlan$b/address > $a
	set -- $(sed "s/:/ /g" $a)
	cp $s $c.new
	for n in $(sed -n "s/^bssid=@LA\([0-9]*\)@$/\1/p" $c.new); do
		sed -i "s/^bssid=@LA$n@$/bssid=$(printf %02x:%s:%s:%s:%02x:%s $((0x$1 | 2)) $2 $3 $4 $((0x$5 ^ n)) $6)/" $c.new
	done
	k=0
	while [ $((1 << k)) -lt "$(grep -c "^bssid=@MB" $c.new)" ]; do k=$((k + 1)); done
	for n in $(sed -n "s/^bssid=@MB\([0-9]*\)@$/\1/p" $c.new); do
		sed -i "s/^bssid=@MB$n@$/bssid=$(printf %02x:%s:%s:%s:%02x:%02x $((0x$1 | 2)) $2 $3 $4 $((0x$5 ^ 3)) $(((0x$6 & ~((1 << k) - 1)) + n)))/" $c.new
	done
	# hostapd takes the transmitted BSS's address from the interface.
	t=$(sed -n "s/^bssid=//p" $c.new | head -1)
	if [ $k -gt 0 ] && [ "$(cat /sys/class/net/wlan$b/address)" != "$t" ]; then
		ip link set wlan$b down
		ip link set wlan$b address "$t"
		ip link set wlan$b up
	fi
	for v in $(sed -n "s#^vlan_file=/run/hostapd-u6e/\(wlan[0-9-]*\)\.vlan\$#\1#p" $c.new); do
		for id in $WIFI_VLANS; do echo "$id $v.$id br$id"; done > /run/hostapd-u6e/$v.vlan.new
		mv /run/hostapd-u6e/$v.vlan.new /run/hostapd-u6e/$v.vlan
	done
	chmod 600 $c.new
	mv $c.new $c
done
)
run() {
confs=
for i in wlan6 wlan24 wlan5; do
	[ -e /sys/class/net/$i ] && confs="$confs /run/hostapd-u6e/$i.conf" || echo "$i: no such radio"
done
exec hostapd -s -P /run/hostapd-u6e/hostapd.pid $confs
}
post() {
for i in wlan24 wlan5 wlan6; do
	for _ in $(seq 60); do
		hostapd_cli -p /run/hostapd -i $i status 2>/dev/null | grep -qx state=ENABLED && break
		sleep 0.5
	done
done
for b in 24 5 6; do
	[ -e /run/u6e-wifi/wlan$b.txpower ] && iw dev wlan$b set txpower fixed $(($(cat /run/u6e-wifi/wlan$b.txpower) * 100))
done
ifs='wlan5 wlan6'
for i in $ifs; do
	own=$(hostapd_cli -p /run/hostapd -i $i show_neighbor 2>/dev/null | grep " stat$") || continue
	nr=${own#*nr=}; nr=${nr%% *}
	case $i in wlan6*) bits=0x01 ;; *) bits=0x11 ;; esac
	b8=$(printf %02x $((0x$(echo "$nr" | cut -c17-18) | bits)))
	nr=$(echo "$nr" | cut -c1-16)$b8$(echo "$nr" | cut -c19-)
	for j in $ifs; do
		[ $j = $i ] || hostapd_cli -p /run/hostapd -i $j set_neighbor ${own%% *} ssid=$(echo "$own" | sed "s/.*ssid=\([0-9a-f]*\).*/\1/") nr=$nr >/dev/null
	done
done
ifs='wlan24 wlan5-1'
for i in $ifs; do
	own=$(hostapd_cli -p /run/hostapd -i $i show_neighbor 2>/dev/null | grep " stat$") || continue
	nr=${own#*nr=}; nr=${nr%% *}
	case $i in wlan6*) bits=0x01 ;; *) bits=0x11 ;; esac
	b8=$(printf %02x $((0x$(echo "$nr" | cut -c17-18) | bits)))
	nr=$(echo "$nr" | cut -c1-16)$b8$(echo "$nr" | cut -c19-)
	for j in $ifs; do
		[ $j = $i ] || hostapd_cli -p /run/hostapd -i $j set_neighbor ${own%% *} ssid=$(echo "$own" | sed "s/.*ssid=\([0-9a-f]*\).*/\1/") nr=$nr >/dev/null
	done
done
ifs='wlan24-1 wlan5-2 wlan6-1'
for i in $ifs; do
	own=$(hostapd_cli -p /run/hostapd -i $i show_neighbor 2>/dev/null | grep " stat$") || continue
	nr=${own#*nr=}; nr=${nr%% *}
	case $i in wlan6*) bits=0x01 ;; *) bits=0x11 ;; esac
	b8=$(printf %02x $((0x$(echo "$nr" | cut -c17-18) | bits)))
	nr=$(echo "$nr" | cut -c1-16)$b8$(echo "$nr" | cut -c19-)
	for j in $ifs; do
		[ $j = $i ] || hostapd_cli -p /run/hostapd -i $j set_neighbor ${own%% *} ssid=$(echo "$own" | sed "s/.*ssid=\([0-9a-f]*\).*/\1/") nr=$nr >/dev/null
	done
done
for i in wlan24 wlan5 wlan6; do
	echo "== $i: $(hostapd_cli -p /run/hostapd -i $i status 2>/dev/null | grep -E "^(state|freq|channel|ssid\[[0-9]\]|num_sta\[[0-9]\])=" | tr "\n" " ")"
done
}
stop() {
for c in /run/hostapd/*; do
	i=${c##*/}
	for sta in $(hostapd_cli -p /run/hostapd -i $i list_sta 2>/dev/null); do
		hostapd_cli -p /run/hostapd -i $i bss_tm_req $sta bss_term=0,1 mbo=0:0 >/dev/null
	done
done
sleep 1
}
"$1"
